begin;
create function pg_temp.assert_true(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;end $$;
insert into auth.users(id,email,email_confirmed_at) values('00000000-0000-4000-8000-00000000ee01','recurrence-test@example.invalid',now()),('00000000-0000-4000-8000-00000000ee03','recurrence-other@example.invalid',now());
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-00000000ee01","role":"authenticated","aal":"aal1"}',true);
set local role authenticated;
insert into public.atraction_tenants(id,name,owner_id) values('00000000-0000-4000-8000-00000000ee02','Recorrência teste','00000000-0000-4000-8000-00000000ee01');
select public.atraction_create_recurrence('00000000-0000-4000-8000-00000000ee02','00000000-0000-4000-8000-00000000ee04','{"title":"Assinatura","direction":"expense","amount_cents":9900,"category":"Serviços","due_date":"2028-01-31"}');
select pg_temp.assert_true((select count(*)=12 and min(amount_cents)=9900 and max(amount_cents)=9900 from public.atraction_finance),'12 full monthly amounts');
select pg_temp.assert_true(exists(select 1 from public.atraction_finance where due_date='2028-02-29'),'leap year');
select public.atraction_create_recurrence('00000000-0000-4000-8000-00000000ee02','00000000-0000-4000-8000-00000000ee04','{"title":"Assinatura","direction":"expense","amount_cents":9900,"category":"Serviços","due_date":"2028-01-31"}');
select pg_temp.assert_true((select count(*)=12 from public.atraction_finance),'idempotent retry');
reset role;
select atraction_private.generate_recurrence('00000000-0000-4000-8000-00000000ee04','2028-03-31');
set local role authenticated;
select pg_temp.assert_true((select count(*)=14 from public.atraction_finance),'scheduler extends horizon');
select public.atraction_record_payment((select id from public.atraction_finance where recurrence_index=0),100,current_date,null,'00000000-0000-4000-8000-00000000ee05',null);
select public.atraction_stop_recurrence('00000000-0000-4000-8000-00000000ee04');
select pg_temp.assert_true((select count(*)=1 from public.atraction_finance where deleted_at is null),'preserve partial payment on cancellation');
reset role;
select atraction_private.generate_recurrence('00000000-0000-4000-8000-00000000ee04','2029-03-31');
set local role authenticated;
select pg_temp.assert_true((select count(*)=14 from public.atraction_finance),'no generation after cancellation');
select public.atraction_create_recurrence('00000000-0000-4000-8000-00000000ee02','00000000-0000-4000-8000-00000000ee06','{"title":"Receita mensal","direction":"income","amount_cents":10000,"category":"Serviços","due_date":"2028-01-31"}','2028-03-31');
select pg_temp.assert_true((select count(*)=3 from public.atraction_finance where recurrence_id='00000000-0000-4000-8000-00000000ee06'),'end date honored');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-00000000ee03","role":"authenticated","aal":"aal1"}',true);
select pg_temp.assert_true((select count(*)=0 from public.atraction_recurrences),'tenant isolation');
do $$begin begin perform public.atraction_stop_recurrence('00000000-0000-4000-8000-00000000ee06');raise exception 'FAIL: cross tenant stop';exception when raise_exception then if sqlerrm like 'FAIL:%' then raise;end if;end;end $$;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-00000000ee01","role":"authenticated","aal":"aal1"}',true);
select pg_temp.assert_true((select count(*)=2 from public.atraction_recurrences),'owner password session reads recurrences');
select 'recurrences permissions, dates, amounts, generation and cancellation passed' as result;
rollback;
